describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against original subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // 10% of 10000 = 1000
      const p2 = new FixedAmountDiscountPolicy(500); // 500
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("can exceed subtotal (caller clamps)", () => {
      const p1 = new PercentageDiscountPolicy(80); // 80% of 1000 = 800
      const p2 = new FixedAmountDiscountPolicy(500); // min(500, 1000) = 500
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      // sum = 1300, which exceeds 1000 — that's OK, Cart clamps
      expect(composite.computeDiscountCents(1000)).toBe(1300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("defaults to sum mode when not specified", () => {
      const p1 = new PercentageDiscountPolicy(10);
      const p2 = new FixedAmountDiscountPolicy(200);
      const composite = new CompositeDiscountPolicy([p1, p2]);
      // sum: 10% of 5000 = 500, + 200 = 700
      expect(composite.computeDiscountCents(5000)).toBe(700);
    });

    it("ignores negative individual policy results (clamps to 0)", () => {
      // NoDiscountPolicy returns 0, which is fine; a hypothetical negative
      // return would be clamped to 0 by the Math.max(0, ...) in sum mode
      const noDiscount = new NoDiscountPolicy();
      const fixed = new FixedAmountDiscountPolicy(300);
      const composite = new CompositeDiscountPolicy([noDiscount, fixed], "sum");
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially to remaining subtotal", () => {
      // 10% of 10000 = 1000, remaining = 9000; 500 off 9000 = 500, remaining = 8500
      const p1 = new PercentageDiscountPolicy(10);
      const p2 = new FixedAmountDiscountPolicy(500);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("order matters in chain mode", () => {
      // Order A: Fixed 500 first → remaining 9500, then 10% of 9500 = 950 → total 1450
      const compositeA = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // Order B: 10% first → 1000 off, remaining 9000, then Fixed 500 → total 1500
      const compositeB = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      expect(compositeA.computeDiscountCents(10000)).toBe(1450);
      expect(compositeB.computeDiscountCents(10000)).toBe(1500);
    });

    it("stops early when remaining reaches 0", () => {
      const p1 = new PercentageDiscountPolicy(100); // 100% → takes all
      const p2 = new FixedAmountDiscountPolicy(500); // nothing left
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      expect(composite.computeDiscountCents(2000)).toBe(2000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("chain with single policy equals that policy alone", () => {
      const p = new PercentageDiscountPolicy(25);
      const composite = new CompositeDiscountPolicy([p], "chain");
      expect(composite.computeDiscountCents(8000)).toBe(
        p.computeDiscountCents(8000),
      );
    });
  });
});

