describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: 5.5 }]),
      ).toThrow(RangeError);
    });

    it("rejects invalid overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 2000, costCents: 700 },
      { upToGrams: 5000, costCents: 1200 },
    ];
    const calc = new WeightBasedShippingCalculator(brackets);

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 for zero-weight items", () => {
      expect(calc.computeShippingCents([line("a", 100, 2)], 200)).toBe(0);
    });

    it("selects first bracket when weight is at boundary", () => {
      // 500g exactly → first bracket (300)
      expect(
        calc.computeShippingCents([line("a", 100, 1, 500)], 100),
      ).toBe(300);
    });

    it("selects second bracket for weight just above first boundary", () => {
      // 501g → second bracket (700)
      expect(
        calc.computeShippingCents([line("a", 100, 1, 501)], 100),
      ).toBe(700);
    });

    it("selects bracket for weight within range", () => {
      // 1000g → second bracket (700)
      expect(
        calc.computeShippingCents([line("a", 100, 1, 1000)], 100),
      ).toBe(700);
    });

    it("selects last bracket at its boundary", () => {
      // 5000g → third bracket (1200)
      expect(
        calc.computeShippingCents([line("a", 100, 1, 5000)], 100),
      ).toBe(1200);
    });

    it("uses last bracket cost as overflow default", () => {
      // 6000g > 5000g, no overflowCostCents → use last bracket (1200)
      expect(
        calc.computeShippingCents([line("a", 100, 1, 6000)], 100),
      ).toBe(1200);
    });

    it("uses overflowCostCents when provided and weight exceeds max bracket", () => {
      const calcWithOverflow = new WeightBasedShippingCalculator(brackets, 2000);
      expect(
        calcWithOverflow.computeShippingCents([line("a", 100, 1, 6000)], 100),
      ).toBe(2000);
    });

    it("sums weight across multiple lines", () => {
      // 2 items of 300g = 600g → second bracket (700)
      expect(
        calc.computeShippingCents([line("a", 100, 2, 300)], 200),
      ).toBe(700);
    });

    it("sorts brackets regardless of input order", () => {
      const unordered = new WeightBasedShippingCalculator([
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
      ]);
      // 400g → first bracket (300)
      expect(
        unordered.computeShippingCents([line("a", 100, 1, 400)], 100),
      ).toBe(300);
    });
  });
});

