      expect(err.productId).toBe("a");
      expect(err.requested).toBe(5);
      expect(err.available).toBe(2);
      expect(err.message).toBe("low stock");
    }
  });

  it("throws InventoryError on partial-stock denial (available but insufficient qty)", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(10);
      expect(err.available).toBe(3);
    }
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(0),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const cart = new Cart({ discountPolicy, region: "US" });
    cart.add(product("a", 10000), 1);
    const result = await cart.checkout({ asyncTaxProvider });
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
    // 10% of 10000 = 1000
    expect(result.totals.taxCents).toBe(1000);
  });

  it("combines price refresh, inventory check, and async tax", async () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(300),
    };
    const cart = new Cart({ discountPolicy, shippingCalculator, region: "FR" });
    cart.add(product("a", 1000), 2);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1200),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.2),
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });

    // Refreshed subtotal: 1200 * 2 = 2400
    expect(result.totals.subtotalCents).toBe(2400);
    // Discount clamped: min(500, 2400) = 500
    expect(result.totals.discountCents).toBe(500);
    // Discounted: 2400 - 500 = 1900
    // Tax: 20% of 1900 = 380
    expect(result.totals.taxCents).toBe(380);
    expect(result.totals.shippingCents).toBe(300);
    // Total: 1900 + 380 + 300 = 2580
    expect(result.totals.totalCents).toBe(2580);
  });

  it("propagates priceFetcher errors", async () => {
    const cart = new Cart();
    cart.add(product("a", 100), 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price API down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price API down",
    );
  });

  it("propagates asyncTaxProvider errors", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("first inventory denial wins when multiple items fail", async () => {
    const cart = new Cart();
    cart.add(product("a", 100), 1);
    cart.add(product("b", 200), 1);
    const inventoryChecker: InventoryChecker = {
      check: vi
        .fn()
        .mockResolvedValueOnce({ available: false, reason: "a is out" })
        .mockResolvedValueOnce({ available: false, reason: "b is out" }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      // First product checked fails — second never checked
      expect((e as InventoryError).productId).toBe("a");
    }
    // Only one call because the first denial throws
    expect(inventoryChecker.check).toHaveBeenCalledTimes(1);
  });

  it("checkout does not mutate cart internal state", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(2000),
    };
    await cart.checkout({ priceFetcher });
    // Internal price should still be 1000 (refresh works on a snapshot)
    const snap = cart.snapshot();
    expect(snap[0]!.product.unitPriceCents).toBe(1000);
    expect(cart.itemCount).toBe(2);
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([0, 100, 999_99, -50])("returns 0 for subtotal %i", (subtotal) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, 101, NaN, Infinity, -Infinity])(
      "rejects out-of-range percent %s",
      (p) => {
        expect(() => new PercentageDiscountPolicy(p)).toThrow(RangeError);
      },
    );

    it.each([0, 50, 100])("accepts valid percent %i", (p) => {
      expect(() => new PercentageDiscountPolicy(p)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 10000 as 1000", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(10000)).toBe(1000);
    });

    it("rounds down to nearest cent", () => {
      // 33% of 100 = 33.0, 33% of 101 = 33.33 → 33
      const policy = new PercentageDiscountPolicy(33);
      expect(policy.computeDiscountCents(101)).toBe(33);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("100% discount returns full subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5000)).toBe(5000);
    });

    it("0% discount returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });

    it("handles large subtotal", () => {
      const policy = new PercentageDiscountPolicy(15);
      expect(policy.computeDiscountCents(1_000_000_00)).toBe(15_000_000);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, -100])("rejects negative amountCents %i", (amt) => {
      expect(() => new FixedAmountDiscountPolicy(amt)).toThrow(RangeError);
    });

    it("rejects non-integer amountCents", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts 0", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns amountCents when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("clamps to subtotal when amountCents exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(2000);
      expect(policy.computeDiscountCents(500)).toBe(500);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns exact subtotal when amountCents equals subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(1000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against original subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // 10% of 10000 = 1000
      const p2 = new FixedAmountDiscountPolicy(500); // 500
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("can exceed subtotal (caller clamps)", () => {
      const p1 = new PercentageDiscountPolicy(80); // 80% of 1000 = 800
      const p2 = new FixedAmountDiscountPolicy(500); // min(500, 1000) = 500
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      // sum = 1300, which exceeds 1000 — that's OK, Cart clamps
      expect(composite.computeDiscountCents(1000)).toBe(1300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("defaults to sum mode when not specified", () => {
      const p1 = new PercentageDiscountPolicy(10);
      const p2 = new FixedAmountDiscountPolicy(200);
      const composite = new CompositeDiscountPolicy([p1, p2]);
      // sum: 10% of 5000 = 500, + 200 = 700
      expect(composite.computeDiscountCents(5000)).toBe(700);
    });

    it("ignores negative individual policy results (clamps to 0)", () => {
      // NoDiscountPolicy returns 0, which is fine; a hypothetical negative
      // return would be clamped to 0 by the Math.max(0, ...) in sum mode
      const noDiscount = new NoDiscountPolicy();
      const fixed = new FixedAmountDiscountPolicy(300);
      const composite = new CompositeDiscountPolicy([noDiscount, fixed], "sum");
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially to remaining subtotal", () => {
      // 10% of 10000 = 1000, remaining = 9000; 500 off 9000 = 500, remaining = 8500
      const p1 = new PercentageDiscountPolicy(10);
      const p2 = new FixedAmountDiscountPolicy(500);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("order matters in chain mode", () => {
      // Order A: Fixed 500 first → remaining 9500, then 10% of 9500 = 950 → total 1450
      const compositeA = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // Order B: 10% first → 1000 off, remaining 9000, then Fixed 500 → total 1500
      const compositeB = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      expect(compositeA.computeDiscountCents(10000)).toBe(1450);
      expect(compositeB.computeDiscountCents(10000)).toBe(1500);
    });

    it("stops early when remaining reaches 0", () => {
      const p1 = new PercentageDiscountPolicy(100); // 100% → takes all
      const p2 = new FixedAmountDiscountPolicy(500); // nothing left
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      expect(composite.computeDiscountCents(2000)).toBe(2000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("chain with single policy equals that policy alone", () => {
      const p = new PercentageDiscountPolicy(25);
      const composite = new CompositeDiscountPolicy([p], "chain");
      expect(composite.computeDiscountCents(8000)).toBe(
        p.computeDiscountCents(8000),
      );
    });
  });
});

