describe("refreshPrices", () => {
  const makeLines = (): CartLine[] => [
    { product: { id: "p1", name: "Widget", unitPriceCents: 100 }, quantity: 2 },
    { product: { id: "p2", name: "Gadget", unitPriceCents: 200 }, quantity: 1 },
  ];

  it("updates prices from fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi
        .fn()
        .mockResolvedValueOnce(150)
        .mockResolvedValueOnce(250),
    };
    const result = await refreshPrices(makeLines(), fetcher);
    expect(result).toHaveLength(2);
    expect(result[0]!.product.unitPriceCents).toBe(150);
    expect(result[0]!.quantity).toBe(2);
    expect(result[1]!.product.unitPriceCents).toBe(250);
    expect(result[1]!.quantity).toBe(1);
  });

  it("preserves other product fields", async () => {
    const lines: CartLine[] = [
      {
        product: { id: "p1", name: "Widget", unitPriceCents: 100, weightGrams: 500, currency: "EUR" },
        quantity: 1,
      },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(300),
    };
    const result = await refreshPrices(lines, fetcher);
    expect(result[0]!.product.weightGrams).toBe(500);
    expect(result[0]!.product.currency).toBe("EUR");
    expect(result[0]!.product.name).toBe("Widget");
  });

  it("throws on negative fetched price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-10),
    };
    await expect(refreshPrices(makeLines(), fetcher)).rejects.toThrow(
      RangeError,
    );
  });

  it("throws on non-integer fetched price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    await expect(refreshPrices(makeLines(), fetcher)).rejects.toThrow(
      RangeError,
    );
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
    };
    await expect(refreshPrices(makeLines(), fetcher)).rejects.toThrow(
      "fetch failed",
    );
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import { InventoryError } from "../src/inventory.ts";
import type { Product, CartLine } from "../src/product.ts";

function product(
  id: string,
  unitPriceCents: number,
  weightGrams?: number,
): Product {
  return { id, name: `Product ${id}`, unitPriceCents, weightGrams };
}

describe("Cart — line management", () => {
  it("adds a product and tracks quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    expect(cart.itemCount).toBe(2);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0]!.product.id).toBe("a");
    expect(snap[0]!.quantity).toBe(2);
  });

  it("merges quantities when adding the same product twice", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    cart.add(product("a", 1000), 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.snapshot()).toHaveLength(1);
  });

  it("rejects non-positive quantity in add", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a", 100), 0)).toThrow(RangeError);
    expect(() => cart.add(product("a", 100), -1)).toThrow(RangeError);
    expect(() => cart.add(product("a", 100), 1.5)).toThrow(RangeError);
  });

  it("rejects negative unit price in add", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
  });

  it("remove returns true for existing product", () => {
    const cart = new Cart();
    cart.add(product("a", 100), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 100), 3);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the product", () => {
    const cart = new Cart();
    cart.add(product("a", 100), 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toHaveLength(0);
  });

  it("updateQuantity rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 100), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 100), 1);
    expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("nope", 1)).toThrow(
      "Product nope is not in the cart",
    );
  });

  it("clear empties the cart", () => {
    const cart = new Cart();
    cart.add(product("a", 100), 1);
    cart.add(product("b", 200), 2);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toHaveLength(0);
  });

  it("snapshot returns a deep copy", () => {
    const cart = new Cart();
    cart.add(product("a", 100), 1);
    const snap = cart.snapshot();
    snap[0]!.quantity = 999;
    snap[0]!.product.unitPriceCents = 0;
    // Cart should be unaffected
    const snap2 = cart.snapshot();
    expect(snap2[0]!.quantity).toBe(1);
    expect(snap2[0]!.product.unitPriceCents).toBe(100);
  });
});

describe("Cart — totals (pricing pipeline)", () => {
  it("computes subtotal as sum of unitPrice * quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2); // 2000
    cart.add(product("b", 500), 3); // 1500
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(3500);
  });

  it("empty cart has all-zero totals", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("uses injected discount policy", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(product("a", 2000), 1);
    const totals = cart.totals();
    expect(discountPolicy.computeDiscountCents).toHaveBeenCalledWith(2000);
    expect(totals.discountCents).toBe(500);
    expect(totals.totalCents).toBe(2000 - 500); // 1500
  });

  it("clamps discount to [0, subtotal]", () => {
    // Discount exceeds subtotal
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(5000),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(1000); // clamped to subtotal
    expect(totals.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("tax is computed on discounted subtotal", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(100),
    };
    const cart = new Cart({ discountPolicy, taxCalculator, region: "US-CA" });
    cart.add(product("a", 2000), 1);
    cart.totals();
    // Tax should be called with discounted subtotal (2000 - 500 = 1500)
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1500, "US-CA");
  });

  it("shipping is computed against discounted subtotal", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };
    const cart = new Cart({ discountPolicy, shippingCalculator });
    cart.add(product("a", 1000), 1);
    cart.totals();
    expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      800, // 1000 - 200
    );
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(300),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(70),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy, taxCalculator, shippingCalculator });
    cart.add(product("a", 2000), 1);
    const totals = cart.totals();
    // subtotal=2000, discount=300, discounted=1700, tax=70, shipping=500
    expect(totals.subtotalCents).toBe(2000);
    expect(totals.discountCents).toBe(300);
    expect(totals.taxCents).toBe(70);
    expect(totals.shippingCents).toBe(500);
    expect(totals.totalCents).toBe(1700 + 70 + 500);
  });

  it("clamps negative tax to 0", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-50),
    };
    const cart = new Cart({ taxCalculator });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-50),
    };
    const cart = new Cart({ shippingCalculator });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("defaults to US region", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator });
    cart.add(product("a", 1000), 1);
    cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1000, "US");
  });
});

